import Handlebars from 'handlebars';
import concat from '../helper/string/concat.js';

Handlebars.registerHelper('concat', concat);

describe('concat helper', () => {

  // Тест для об'єднання декількох рядків
  it('should concatenate multiple strings', () => {
    const template = Handlebars.compile('{{concat "Hello" " " "World"}}');
    const result = template({});
    expect(result).toBe('Hello World');
  });

  // Тест для об'єднання рядків і чисел
  it('should concatenate strings and numbers', () => {
    const template = Handlebars.compile('{{concat "Item" 123}}');
    const result = template({});
    expect(result).toBe('Item123');
  });

  // Тест для об'єднання змінних із контексту
  it('should concatenate variables from the context', () => {
    const template = Handlebars.compile('{{concat "https://example.com/" id}}');
    const result = template({ id: '12345' });
    expect(result).toBe('https://example.com/12345');
  });

  // Тест для перевірки порожніх рядків
  it('should ignore empty strings and only concatenate non-empty values', () => {
    const template = Handlebars.compile('{{concat "Hello" "" "World"}}');
    const result = template({});
    expect(result).toBe('HelloWorld');
  });

  // Тест для перевірки числових значень
  it('should concatenate numbers', () => {
    const template = Handlebars.compile('{{concat 1 2 3}}');
    const result = template({});
    expect(result).toBe('123');
  });

  // Тест для перевірки, чи повертає порожній рядок для відсутніх аргументів
  it('should return an empty string if no arguments are provided', () => {
    const template = Handlebars.compile('{{concat}}');
    const result = template({});
    expect(result).toBe('');
  });

  // Тест для некоректних типів даних (об'єкти, масиви)
  it('should ignore non-string and non-number types like objects or arrays', () => {
    const template = Handlebars.compile('{{concat "Prefix-" obj "Postfix"}}');
    const result = template({ obj: { key: 'value' } });
    expect(result).toBe('Prefix-Postfix');
  });
});
